<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$id=(int)($_GET['id']??0);$pdo=db();$st=$pdo->prepare('SELECT p.*,COUNT(v.id) visits FROM patients p LEFT JOIN visits v ON v.patient_id=p.id WHERE p.id=? GROUP BY p.id');$st->execute([$id]);$p=$st->fetch();if(!$p)redirect('patients.php');$st=$pdo->prepare('SELECT v.*,s.full_name doctor FROM visits v LEFT JOIN staff s ON s.id=v.doctor_id WHERE v.patient_id=? ORDER BY v.visit_date DESC');$st->execute([$id]);$visits=$st->fetchAll();$st=$pdo->prepare('SELECT a.*,d.name department FROM admissions a LEFT JOIN wards w ON w.id=a.bed_id LEFT JOIN departments d ON d.id=NULL WHERE a.patient_id=? ORDER BY a.admitted_at DESC');$st->execute([$id]);$admissions=$st->fetchAll();admin_header('Patient Record','patients.php');?><div class="pagehead"><div><h1><?=e($p['full_name'])?></h1><div class="muted"><?=e($p['patient_no'])?> · <?=e($p['phone'])?></div></div><a class="btn" href="visits.php?action=new&patient_id=<?=$p['id']?>">New visit</a></div><div class="grid"><div class="card"><h3>Demographics</h3><p><b>DOB:</b> <?=e($p['date_of_birth'])?></p><p><b>Gender:</b> <?=e($p['gender'])?></p><p><b>Address:</b> <?=e($p['address'])?></p><p><b>Next of kin:</b> <?=e($p['next_of_kin'])?> <?=e($p['next_of_kin_phone'])?></p></div><div class="card"><h3>Activity</h3><p><b>Visits:</b> <?=$p['visits']?></p><a class="btn secondary" href="billing.php?patient_id=<?=$p['id']?>">Billing</a> <a class="btn secondary" href="laboratory.php?patient_id=<?=$p['id']?>">Laboratory</a></div></div><div class="card" style="margin-top:18px"><h2>Clinical visits</h2><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Type</th><th>Doctor</th><th>Complaint</th><th>Diagnosis</th><th>Status</th></tr><?php foreach($visits as $v):?><tr><td><?=e($v['visit_date'])?></td><td><?=e($v['visit_type'])?></td><td><?=e($v['doctor'])?></td><td><?=e($v['chief_complaint'])?></td><td><?=e($v['diagnosis'])?></td><td><?=e($v['status'])?></td></tr><?php endforeach;?></table></div></div><?php admin_footer();
